package app.eversage.offline;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.webkit.*;import android.view.*;import android.net.Uri;import android.graphics.*;import android.provider.MediaStore;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public class LiteActivity extends Activity {
 WebView web;ExecutorService worker=Executors.newSingleThreadExecutor();byte[] pendingSave;
 public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);web.setBackgroundColor(Color.rgb(255,252,246));setContentView(web);web.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Bridge(),"Native");web.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!"app.eversage.local".equals(u.getHost()))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));String p=u.getPath().substring(1);if(p.isEmpty())p="index.html";if(p.contains(".."))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));try{return new WebResourceResponse(p.endsWith(".js")?"text/javascript":p.endsWith(".css")?"text/css":p.endsWith(".json")?"application/json":p.endsWith(".webp")?"image/webp":p.endsWith(".png")?"image/png":"text/html","UTF-8",(p.equals("generated/share.png")?new FileInputStream(new File(getCacheDir(),"shared/preview.png")):getAssets().open(p)));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !"app.eversage.local".equals(r.getUrl().getHost());}});web.loadUrl("https://app.eversage.local/index.html"+(getIntent().getBooleanExtra("daily",false)?"#daily":""));}
 void emit(String event,JSONObject value){runOnUiThread(()->{if(web!=null)web.evaluateJavascript("window.dispatchEvent(new CustomEvent("+JSONObject.quote(event)+",{detail:"+value.toString()+"}));",null);});}
 void message(String text){try{emit("nativeMessage",new JSONObject().put("message",text));}catch(Exception ignored){}}
 public void onBackPressed(){web.evaluateJavascript("window.appBack&&window.appBack()",null);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==12&&result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingSave!=null){final byte[] bytes=pendingSave;pendingSave=null;final Uri target=data.getData();worker.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(target)){out.write(bytes);message("Image saved.");}catch(Exception e){message("Could not save the image. Please try again.");}});}}

 byte[] makeCard(String json,boolean withArt)throws Exception {JSONObject e=new JSONObject(json);Bitmap bitmap=Bitmap.createBitmap(1080,1500,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bitmap);c.drawColor(Color.rgb(255,252,246));if(withArt){try(InputStream in=getAssets().open("art/share.webp")){Bitmap bg=BitmapFactory.decodeStream(in);if(bg!=null){c.drawBitmap(bg,null,new Rect(0,0,1080,1500),new Paint(3));bg.recycle();}}}Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(Color.rgb(57,44,37));paint.setTypeface(Typeface.create("serif",Typeface.NORMAL));paint.setTextSize(52);float y=drawWords(c,paint,e.getString("wisdom"),100,560,880,77);paint.setColor(Color.rgb(164,64,29));paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));paint.setTextSize(28);drawWords(c,paint,e.getString("citation"),100,y+60,880,43);paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(24);paint.setColor(Color.rgb(121,103,90));c.drawText("Original EverSage reflection - not a scripture quotation",100,1310,paint);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));paint.setTextSize(36);paint.setColor(Color.rgb(191,76,34));c.drawText("eversage",100,1415,paint);ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);bitmap.recycle();return out.toByteArray();}
 float drawWords(Canvas c,Paint p,String text,float x,float y,float width,float lineHeight){String line="";for(String word:text.split("\\s+")){String next=line.isEmpty()?word:line+" "+word;if(!line.isEmpty()&&p.measureText(next)>width){c.drawText(line,x,y,p);y+=lineHeight;line=word;}else line=next;}if(!line.isEmpty()){c.drawText(line,x,y,p);y+=lineHeight;}return y;}
 public class Bridge {
  @JavascriptInterface public void previewReflection(String json,boolean art){worker.execute(()->{try{File d=new File(getCacheDir(),"shared");d.mkdirs();try(OutputStream out=new FileOutputStream(new File(d,"preview.png"))){out.write(makeCard(json,art));}emit("reflectionPreview",new JSONObject().put("image","https://app.eversage.local/generated/share.png?v="+System.currentTimeMillis()));}catch(Exception e){message("Could not prepare the preview. Please try again.");}});}
  @JavascriptInterface public void shareReflection(String json,boolean art,boolean save){worker.execute(()->{try{String data="data:image/png;base64,"+android.util.Base64.encodeToString(makeCard(json,art),android.util.Base64.NO_WRAP);shareImage(data,save);}catch(Exception e){message("Could not prepare the image. Please try again.");}});}

  @JavascriptInterface public void closeApp(){runOnUiThread(()->finish());}
  @JavascriptInterface public void shareImage(String data,boolean save){worker.execute(()->{try{if(!data.startsWith("data:image/png;base64,")||data.length()>16000000)throw new IOException();byte[] bytes=android.util.Base64.decode(data.substring(data.indexOf(',')+1),0);if(save&&Build.VERSION.SDK_INT>=29){ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"EverSage-"+System.currentTimeMillis()+".png");v.put(MediaStore.Images.Media.MIME_TYPE,"image/png");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/EverSage");Uri u=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(u==null)throw new IOException();try(OutputStream out=getContentResolver().openOutputStream(u)){out.write(bytes);}message("Image saved in Pictures / EverSage.");}else if(save){pendingSave=bytes;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/png").putExtra(Intent.EXTRA_TITLE,"EverSage-wisdom.png");runOnUiThread(()->startActivityForResult(i,12));}else{File dir=new File(getCacheDir(),"shared");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,"wisdom.png"))){out.write(bytes);}Uri u=Uri.parse("content://app.eversage.offline.share/wisdom.png");Intent i=new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,u);i.setClipData(ClipData.newRawUri("EverSage wisdom",u));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);runOnUiThread(()->startActivity(Intent.createChooser(i,"Share wisdom")));}}catch(Exception e){message("Could not prepare the image. Please try again.");}});}
  @JavascriptInterface public void reminder(boolean enabled,int hour,int minute){runOnUiThread(()->{if(enabled&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);try{emit("reminderState",new JSONObject().put("enabled",false));}catch(Exception ignored){}message("Allow notifications, then turn the reminder on again.");return;}AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);PendingIntent p=PendingIntent.getBroadcast(LiteActivity.this,1,new Intent(LiteActivity.this,DailyReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);a.cancel(p);if(enabled){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,Math.max(0,Math.min(23,hour)));c.set(Calendar.MINUTE,Math.max(0,Math.min(59,minute)));c.set(Calendar.SECOND,0);if(c.getTimeInMillis()<=System.currentTimeMillis())c.add(Calendar.DATE,1);a.setInexactRepeating(AlarmManager.RTC_WAKEUP,c.getTimeInMillis(),AlarmManager.INTERVAL_DAY,p);}});}
 }
}
